<?php require_once __DIR__.'/../../config/app.php';if($_SERVER['REQUEST_METHOD']!=='POST')redirect('/pages/auth/register.php');$d=['name'=>trim($_POST['name']??''),'email'=>trim($_POST['email']??''),'password'=>$_POST['password']??'','password_confirmation'=>$_POST['password_confirmation']??''];$er=[];if($d['name']==='')$er['name']='Nama wajib diisi.';if(!filter_var($d['email'],FILTER_VALIDATE_EMAIL))$er['email']='Format email tidak valid.';if(strlen($d['password'])<6)$er['password']='Kata sandi minimal 6 karakter.';if($d['password']!==$d['password_confirmation'])$er['password_confirmation']='Konfirmasi kata sandi tidak sama.';if($er)failForm($er,$d,'/pages/auth/register.php');try{$s=$pdo->prepare('INSERT INTO users(name,email,password,role) VALUES(?,?,?,?)');$s->execute([$d['name'],$d['email'],password_hash($d['password'],PASSWORD_DEFAULT),'user']);$_SESSION['success']='Registrasi berhasil. Silakan masuk.';redirect('/pages/auth/login.php');}catch(PDOException $e){if($e->getCode()==='23000')failForm(['email'=>'Email sudah terdaftar.'],['name'=>$d['name'],'email'=>$d['email']],'/pages/auth/register.php');throw $e;}